package com.campuseventhub;
import java.io.IOException;import java.sql.*;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet("/adminReport") public class AdminReportServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("admin_id")==null){p.sendRedirect("admin-login.jsp");return;}p.setContentType("text/html;charset=UTF-8");StringBuilder b=new StringBuilder("<!DOCTYPE html><html><head><title>Reports</title><style>body{font-family:Arial;background:#f4f6f8;padding:25px}table{width:100%;background:white;border-collapse:collapse;margin-bottom:30px}th{background:#2c3e50;color:white;padding:10px}td{padding:10px;text-align:center;border:1px solid #ddd}.back{padding:10px 18px;background:#555;color:white;text-decoration:none;border-radius:5px}</style></head><body><h1>Event Reports</h1><h2>Event-wise Registrations</h2><table><tr><th>Event</th><th>Category</th><th>Capacity</th><th>Registrations</th><th>Approved</th><th>Attended</th><th>Average Rating</th></tr>");try(Connection c=DBConnection.getConnection();PreparedStatement x=c.prepareStatement("SELECT e.event_name,e.category,e.capacity,COUNT(er.registration_id) registrations,SUM(er.status='Approved') approved,SUM(er.attended=1) attended,COALESCE(ROUND(AVG(f.rating),2),0) avg_rating FROM events e LEFT JOIN event_registrations er ON e.event_id=er.event_id LEFT JOIN feedback f ON e.event_id=f.event_id GROUP BY e.event_id ORDER BY e.event_date")){ResultSet z=x.executeQuery();while(z.next())b.append("<tr><td>"+z.getString("event_name")+"</td><td>"+z.getString("category")+"</td><td>"+z.getInt("capacity")+"</td><td>"+z.getInt("registrations")+"</td><td>"+z.getInt("approved")+"</td><td>"+z.getInt("attended")+"</td><td>"+z.getDouble("avg_rating")+" / 5</td></tr>");}catch(Exception e){b.append("<tr><td colspan='7'>Error: "+e.getMessage()+"</td></tr>");}b.append("</table><h2>Recent Feedback</h2><table><tr><th>Student</th><th>Event</th><th>Rating</th><th>Comment</th><th>Date</th></tr>");try(Connection c=DBConnection.getConnection();PreparedStatement x=c.prepareStatement("SELECT s.name,e.event_name,f.rating,f.comment,f.feedback_date FROM feedback f JOIN students s ON f.student_id=s.student_id JOIN events e ON f.event_id=e.event_id ORDER BY f.feedback_id DESC")){ResultSet z=x.executeQuery();while(z.next())b.append("<tr><td>"+z.getString("name")+"</td><td>"+z.getString("event_name")+"</td><td>"+z.getInt("rating")+" / 5</td><td>"+z.getString("comment")+"</td><td>"+z.getDate("feedback_date")+"</td></tr>");}catch(Exception e){b.append("<tr><td colspan='5'>Error: "+e.getMessage()+"</td></tr>");}b.append("</table><a class='back' href='admin-dashboard.jsp'>Back to Dashboard</a></body></html>");p.getWriter().print(b.toString());}}
